import React, { useEffect, useState } from "react";
import Navbar from "../Components/Navbar";
import Footer from "../Components/Footer";
import API_BASE_URL from "../config";
import "../App.css";

const MySales = () => {
  const userId = sessionStorage.getItem("userId");
  const [sales, setSales] = useState([]);
  const [totalEarnings, setTotalEarnings] = useState(0);

  useEffect(() => {
    fetch(`${API_BASE_URL}/api/sales/user/${userId}`)
      .then((res) => res.json())
      .then((data) => {
        setSales(data);
        const total = data.reduce((sum, item) => sum + parseFloat(item.price), 0);
        setTotalEarnings(total);
      })
      .catch((err) => console.error("Error loading sales:", err));
  }, [userId]);

  const markAsShipped = async (id) => {
    try {
      await fetch(`${API_BASE_URL}/api/listings/${id}/shipped`, {
        method: "PUT",
      });
      setSales((prev) =>
        prev.map((item) =>
          item.id === id ? { ...item, shipped: true } : item
        )
      );
    } catch (err) {
      console.error("Error updating shipped status:", err);
    }
  };

  return (
    <div className="dashboard-wrapper">
      <Navbar />
      <main className="sales-container">
        <h2>My Sales</h2>
        <p className="earnings-summary">
          💰 <strong>Total Earnings:</strong> ${totalEarnings.toFixed(2)}
        </p>

        <div className="sales-grid">
          {sales.map((item) => (
            <div key={item.id} className="sales-card">
              <img src={item.image} alt={item.title} className="sales-thumb" />
              <div className="sales-details">
                <h4>{item.title}</h4>
                <p>{item.description}</p>
                <p><strong>Price:</strong> ${parseFloat(item.price).toFixed(2)}</p>
                <p><strong>Condition:</strong> {item.condition}</p>
                <p><strong>Status:</strong> {item.shipped ? "✅ Shipped" : "❌ Not Shipped"}</p>
                {!item.shipped && (
                  <button className="ship-btn" onClick={() => markAsShipped(item.id)}>
                    Mark as Shipped
                  </button>
                )}
              </div>
            </div>
          ))}
        </div>
      </main>
      <Footer />
    </div>
  );
};

export default MySales;
